import{_ as s,o as t,c as o,a1 as r}from"./chunks/framework.DdbKPUhY.js";const u=JSON.parse('{"title":"Response API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/response-api.md","filePath":"spec/response-api.md"}'),n={name:"spec/response-api.md"};function i(a,e,l,d,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="response-api-spec" tabindex="-1">Response API Spec <a class="header-anchor" href="#response-api-spec" aria-label="Permalink to &quot;Response API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Response module builds and sends HTTP responses. It provides functions to set response status, headers, body, and control response sending.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-response-set-status" tabindex="-1">uvhttp_response_set_status <a class="header-anchor" href="#uvhttp-response-set-status" aria-label="Permalink to &quot;uvhttp_response_set_status&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_response_set_status(uvhttp_response_t* response, int status_code)</code></li><li><strong>Purpose</strong>: Set the HTTP response status code</li><li><strong>Preconditions</strong>: <code>response</code> must be valid. <code>status_code</code> should be a valid HTTP status code.</li><li><strong>Postconditions</strong>: <code>response-&gt;status_code</code> is set.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: response is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-response-set-header" tabindex="-1">uvhttp_response_set_header <a class="header-anchor" href="#uvhttp-response-set-header" aria-label="Permalink to &quot;uvhttp_response_set_header&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_response_set_header(uvhttp_response_t* response, const char* name, const char* value)</code></li><li><strong>Purpose</strong>: Set a response header</li><li><strong>Preconditions</strong>: <code>response</code> must be valid. <code>name</code> and <code>value</code> must be non-NULL.</li><li><strong>Postconditions</strong>: The header is added to the response. If the header already exists, it is overwritten.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: response, name, or value is NULL</li><li>Header value contains control characters (response splitting guard)</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-response-set-body" tabindex="-1">uvhttp_response_set_body <a class="header-anchor" href="#uvhttp-response-set-body" aria-label="Permalink to &quot;uvhttp_response_set_body&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_response_set_body(uvhttp_response_t* response, const char* body, size_t length)</code></li><li><strong>Purpose</strong>: Set the response body</li><li><strong>Preconditions</strong>: <code>response</code> must be valid. <code>body</code> can be NULL (empty body).</li><li><strong>Postconditions</strong>: The body is copied into the response. Content-Length is NOT set automatically.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: response is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-response-send" tabindex="-1">uvhttp_response_send <a class="header-anchor" href="#uvhttp-response-send" aria-label="Permalink to &quot;uvhttp_response_send&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_response_send(uvhttp_response_t* response)</code></li><li><strong>Purpose</strong>: Send the response to the client</li><li><strong>Preconditions</strong>: <code>response</code> must be valid. Status code must be set.</li><li><strong>Postconditions</strong>: The response is sent. Headers are flushed, then the body is sent.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: response is NULL</li><li><code>UVHTTP_ERROR_RESPONSE_SEND</code>: write failure</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-response-cleanup" tabindex="-1">uvhttp_response_cleanup <a class="header-anchor" href="#uvhttp-response-cleanup" aria-label="Permalink to &quot;uvhttp_response_cleanup&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_response_cleanup(uvhttp_response_t* response)</code></li><li><strong>Purpose</strong>: Free response resources</li><li><strong>Preconditions</strong>: <code>response</code> must be valid.</li><li><strong>Postconditions</strong>: All allocated fields are freed. Pointers are NULLed.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Response ownership</strong>: The framework creates the response object. The handler does not need to allocate or free it.</p></li><li><p><strong>Content-Type</strong>: The handler must set Content-Type explicitly. The framework does not auto-detect.</p></li><li><p><strong>Content-Length</strong>: The framework sets Content-Length from the body length. If no body is set, Content-Length is 0.</p></li><li><p><strong>Response splitting guard</strong>: All header values are checked for control characters (<code>\\r</code>, <code>\\n</code>, <code>\\0</code>) before emission. If detected, the header is rejected.</p></li><li><p><strong>Error responses</strong>: When an error handler is invoked, it should set an appropriate status code (4xx/5xx) and return an error body.</p></li><li><p><strong>Large responses</strong>: For large bodies (&gt;1MB), the handler should use chunked encoding or sendfile for static files.</p></li></ol><h2 id="performance-requirements" tabindex="-1">Performance Requirements <a class="header-anchor" href="#performance-requirements" aria-label="Permalink to &quot;Performance Requirements&quot;">​</a></h2><ul><li>Header emission: O(n) where n = header count</li><li>Body sending: O(body size) for small bodies, zero-copy for large files</li><li>Response header buffer: 4096 bytes (configurable)</li></ul><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Status code setting</li><li>Header setting and overwriting</li><li>Body setting (empty, small, large)</li><li>Response sending</li><li>NULL parameter handling for all functions</li><li>Response splitting guard (control character rejection)</li><li>Cleanup (no leaks)</li></ul>',20)])])}const g=s(n,[["render",i]]);export{u as __pageData,g as default};
